  function inject(){var ev=lastEvent;if(!ev||!ev.podeGerirAtividades||ev.cancelado)return;var host=document.querySelector('section .relative.z-10');if(!host)return;var existing=[].slice.call(document.querySelectorAll('#eh-event-management'));if(existing.length){existing.slice(1).forEach(function(n){n.remove();});if(existing[0].getAttribute('data-event-id')===String(ev.id)){bind(ev);return;}existing[0].remove();}if(injectingEventId===ev.id)return;injectingEventId=ev.id;loadCats().then(function(){var current=[].slice.call(document.querySelectorAll('#eh-event-management'));if(current.length){current.slice(1).forEach(function(n){n.remove();});if(current[0].getAttribute('data-event-id')===String(ev.id)){bind(ev);return;}current[0].remove();}var firstGrid=host.querySelector('[class*="lg:grid-cols-2"]')||host.querySelector('.grid.grid-cols-1');if(!firstGrid)return;firstGrid.insertAdjacentHTML('afterend',panelHtml(ev));bind(ev);}).finally(function(){injectingEventId=null;});}
  function bind(ev){var panel=document.getElementById('eh-event-management');if(!panel)return;var form=panel.querySelector('[data-eh-edit-form]');var toggle=panel.querySelector('[data-eh-edit-event]');var close=panel.querySelector('[data-eh-close-edit]');var cancel=panel.querySelector('[data-eh-cancel-event]');if(toggle)toggle.onclick=function(){form&&form.classList.toggle('hidden');};if(close)close.onclick=function(){form&&form.classList.add('hidden');};if(cancel)cancel.onclick=function(){if(!window.confirm('Pretende mesmo cancelar este evento?'))return;origFetch('/api/eventos/'+ev.id,{method:'DELETE',credentials:'include'}).then(function(r){if(!r.ok)throw new Error();window.location.href='/Home/Index?page=events';}).catch(function(){window.alert('Nao foi possivel cancelar o evento.');});};if(form)form.onsubmit=function(e){e.preventDefault();var fd=new FormData(form);var payload={nome:fd.get('nome'),data:fd.get('data'),horaInicio:fd.get('horaInicio'),local:fd.get('local'),descricao:fd.get('descricao'),capacidade:Number(ev.capacidadeMax||0),idCategoria:fd.get('idCategoria')?Number(fd.get('idCategoria')):null,imageUrl:fd.get('imageUrl')||null};origFetch('/api/eventos/'+ev.id,{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(payload)}).then(function(r){if(!r.ok)return r.text().then(function(t){throw new Error(t||'Erro');});lastEvent=Object.assign({},ev,payload,{id:ev.id,podeGerirAtividades:ev.podeGerirAtividades,eOrganizadorDoEvento:ev.eOrganizadorDoEvento,categoria:ev.categoria,cancelado:ev.cancelado});if(form)form.classList.add('hidden');window.alert('Evento editado com sucesso.');}).catch(function(err){window.alert(err.message||'Nao foi possivel editar o evento.');});};}
